}

// TransferResponse представляет ответ на запрос перевода.
type TransferResponse struct {
	Success   bool    `json:"success"`
	Message   string  `json:"message"`
	RemainingDailyLimit   float64 `json:"remaining_daily_limit"`
	RemainingMonthlyLimit float64 `json:"remaining_monthly_limit"`
}

// ============================================================================
// Интерфейс gRPC-сервиса
// ============================================================================

// TransferServiceServer определяет интерфейс для обработки gRPC-запросов на перевод.
