	// Transfer обрабатывает запрос на перевод средств с проверкой лимитов.
	Transfer(ctx context.Context, req *TransferRequest) (*TransferResponse, error)
}

// ============================================================================
// Структура клиента и лимитов
// ============================================================================

// ClientLimits хранит информацию о суточном и месячном лимитах клиента.
