	DailyLimit   float64
	MonthlyLimit float64
}

// ============================================================================
// Реализация сервиса переводов
// ============================================================================

// TransferService реализует интерфейс TransferServiceServer.
// Управляет обработкой запросов на перевод с проверкой суточных и месячных лимитов.
type TransferService struct {
	db *sql.DB
	// Мьютекс для защиты доступа к данным лимитов в конкурентной среде
	mu sync.RWMutex
	// Кэш текущих использованных лимитов по клиентам
	// Ключ: clientID, Значение: структура с использованными суммами
	usedLimits map[string]*UsedLimits
}

// UsedLimits хранит информацию о уже использованных суммах в текущем периоде.
type UsedLimits struct {
	DailyUsed   float64
	MonthlyUsed float64
	// Дата начала текущего дня (для сброса суточного лимита)
	DayStart    time.Time
	// Дата начала текущего месяца (для сброса месячного лимита)
	MonthStart  time.Time
}

// NewTransferService создаёт новый экземпляр сервиса переводов.
// Принимает соединение с базой данных для хранения информации о клиентах и лимитах.
func NewTransferService(db *sql.DB) *TransferService {
	return &TransferService{
		db:         db,
		usedLimits: make(map[string]*UsedLimits),
	}
}

