public static void ValidateEntry(IReadOnlyList<Posting> postings)
{
    // Проверяем, что в проводке (бухгалтерской записи) есть минимум две строки.
    // Это фундаментальное требование двойной записи: каждая операция должна иметь
    // как минимум один дебет и один кредит.
    if (postings.Count < 2)
        throw new ArgumentException("Entry must have at least two postings");

    // Инициализируем переменные для накопления сумм по дебету и кредиту.
    decimal debit = 0m, credit = 0m;

    // Проходим по всем строкам проводки (постингам).
    foreach (var p in postings)
    {
        // Проверяем, что сумма в каждой строке положительная.
        // Отрицательные или нулевые суммы недопустимы, так как направление
        // (дебет/кредит) уже задано отдельно.
        if (p.Amount <= 0m)
            throw new ArgumentException($"Non-positive amount on account {p.Account}");

        // В зависимости от стороны (дебет или кредит) добавляем сумму
        // к соответствующему итогу.
        if (p.Side == Side.Debit) debit += p.Amount;
        else credit += p.Amount;
    }

    // Проверяем баланс проводки: сумма всех дебетовых строк должна быть
    // равна сумме всех кредитовых строк. Это основное правило бухгалтерского учета.
    if (debit != credit)
        throw new InvalidOperationException($"Unbalanced entry: debit {debit}, credit {credit}");

    // Проверяем, что все строки проводки используют одну и ту же валюту.
    // Смешивание валют в одной проводке недопустимо, так как это нарушает
    // принцип единства измерения и может привести к ошибкам в отчетности.
    if (postings.Select(p => p.Currency).Distinct().Count() > 1)
        throw new InvalidOperationException("Mixed currencies in one entry");
}
