func (l *Ledger) Transfer(from, to *Account, amount int64) error {
    // Проверка валидности операции: сумма должна быть положительной,
    // и нельзя переводить деньги самому себе (отправитель и получатель разные).
    if amount <= 0 || from.ID == to.ID {
        return ErrInvalidTransfer
    }

    // Определяем порядок блокировки мьютексов, чтобы избежать взаимной блокировки (deadlock).
    // Мы всегда блокируем аккаунт с меньшим ID первым, а с большим — вторым.
    // Это гарантирует, что все горутины будут захватывать блокировки в одном и том же порядке.
    first, second := from, to
    if first.ID > second.ID {
        first, second = second, first
    }

    // Блокируем первый аккаунт (с меньшим ID).
    // defer гарантирует, что блокировка будет снята при выходе из функции.
    first.mu.Lock()
    defer first.mu.Unlock()

    // Блокируем второй аккаунт (с большим ID).
    // defer гарантирует, что эта блокировка также будет снята при выходе из функции.
    second.mu.Lock()
    defer second.mu.Unlock()

    // Проверяем, достаточно ли средств на счете отправителя.
    // Важно: проверка выполняется уже после захвата обеих блокировок,
    // чтобы данные о балансе были актуальными и не изменились параллельно.
    if from.Balance < amount {
        return fmt.Errorf("account %d: insufficient funds: have %d, need %d", from.ID, from.Balance, amount)
    }

    // Выполняем сам перевод: списываем сумму со счета отправителя...
    from.Balance -= amount
    // ...и зачисляем её на счет получателя.
    to.Balance += amount

    // Возвращаем nil, так как операция прошла успешно.
    return nil
}
