// Класс, представляющий одну налоговую ставку (бренд)
// upTo — верхняя граница дохода для этой ставки (null означает, что граница отсутствует, т.е. это последняя ставка)
// rate — процентная ставка налога для данного диапазона
data class Bracket(val upTo: BigDecimal?, val rate: BigDecimal)

// Функция для расчета прогрессивного налога
// income — общий доход, с которого нужно рассчитать налог
// brackets — список налоговых ставок, отсортированных по возрастанию границ
// Возвращает итоговую сумму налога, округленную до целого числа
fun progressiveTax(income: BigDecimal, brackets: List<Bracket>): BigDecimal {
    // Проверяем, что доход не отрицательный, иначе выбрасываем исключение
    require(income >= BigDecimal.ZERO) { "income must be non-negative" }

    // Инициализируем переменную для накопления итоговой суммы налога
    var tax = BigDecimal.ZERO
    // Инициализируем нижнюю границу текущего диапазона дохода (начинаем с нуля)
    var lower = BigDecimal.ZERO

    // Проходим по каждой налоговой ставке (бренду)
    for (b in brackets) {
        // Если текущий доход меньше или равен нижней границе диапазона,
        // значит, мы уже обработали все применимые ставки — выходим из цикла
        if (income <= lower) break

        // Определяем верхнюю границу для расчета налога в текущем диапазоне:
        // - Если у ставки есть верхняя граница (upTo != null), берем минимум между этой границей и доходом
        // - Если верхней границы нет (upTo == null), используем весь доход
        val upper = b.upTo?.min(income) ?: income

        // Рассчитываем налог для текущего диапазона:
        // (верхняя граница - нижняя граница) * ставка налога
        // Добавляем полученную сумму к общему налогу
        tax += (upper - lower) * b.rate

        // Обновляем нижнюю границу для следующего диапазона:
        // - Если у текущей ставки есть верхняя граница, она становится нижней для следующего диапазона
        // - Если верхней границы нет (это последняя ставка), выходим из цикла
        lower = b.upTo ?: break
    }

    // Возвращаем итоговую сумму налога, округленную до целого числа
    // с использованием стандартного правила округления (половина вверх)
    return tax.setScale(0, RoundingMode.HALF_UP)
}
