	// 1. Получаем московскую зону времени.
	// В Go можно использовать фиксированную зону UTC+3, так как Москва не переходит на летнее время.
	moscowZone := time.FixedZone("MSK", 3*60*60)

	// 2. Переводим переданное время в московское время.
	// Это ключевой шаг: 22:30 UTC становится 01:30 MSK следующего дня.
	tInMoscow := t.In(moscowZone)

